insert into public.vocabulary_items
(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_evidence','evidence','noun','facts, information or examples that support a conclusion, claim or judgement','[{"senseId":"evidence_1","meaning":"facts, information or examples that support a conclusion, claim or judgement","acceptedParaphrases":["supporting facts","information that backs up a claim"],"masteryContexts":[{"contextId":"u6_21_evidence_meaning","text":"The detective could not arrest anyone because there was not enough evidence to support his theory.","meaning":"facts that support a conclusion","wrongMeanings":["proof that nobody can question","opinions that people share","rules that guide a decision"]},{"contextId":"u6_21_evidence_paraphrase","text":"Students are expected to give evidence from the text when they explain their opinion.","meaning":"information or examples that support a claim","wrongMeanings":["personal feelings about a text","a summary of the whole text","questions about the meaning of a text"]}],"situationDistractors":["The students queued outside the canteen and ordered sandwiches and fruit juice.","A passenger asked the driver to stop at the next corner and stepped off the bus.","Heavy traffic delayed the visitors, who arrived twenty minutes late for the tour.","The museum closes at five on weekdays, so visitors should arrive early.","A boy fed the ducks beside the lake while his sister took photographs.","The mechanic replaced the brakes and test-drove the car around the block."],"gapDistractors":[{"contextId":"u6_21_evidence_gap_1","answer":"evidence","wrong":["holiday","talent","furniture"]},{"contextId":"u6_21_evidence_gap_2","answer":"evidence","wrong":["permission","patience","talent"]},{"contextId":"u6_21_evidence_gap_3","answer":"evidence","wrong":["furniture","machinery","equipment"]}],"spellingErrors":["evidance","evidense","evedence","evidnce","evidencee","eveidence"],"wordFamilyForms":[{"form":"evidence","partOfSpeech":"noun","example":"The police collected evidence from the scene before the road was reopened.","pedagogicallyUseful":true},{"form":"evident","partOfSpeech":"adjective","example":"It became evident that the old method was not working.","pedagogicallyUseful":true,"altExample":"The improvement in her writing was evident after only a few weeks."},{"form":"evidently","partOfSpeech":"adverb","example":"The shop was evidently closed, since the lights were off and the door was locked.","pedagogicallyUseful":true,"altExample":"The road was evidently flooded, so the bus took a different route."}],"masteryPassages":[{"passageId":"u6_21_evidence_passage_1","contextId":"u6_21_evidence_gap_1","text":"A student wrote that homework is useless but did not mention a single study. Her teacher explained that a strong argument needs ____, such as statistics, examples or results from experiments, rather than personal opinion alone.","answer":"evidence"},{"passageId":"u6_21_evidence_passage_2","contextId":"u6_21_evidence_gap_2","text":"The detective listened carefully to every witness, yet he refused to name the thief. Without enough ____ to support his theory, he knew that an accusation could be wrong.","answer":"evidence"}],"contextDependentParaphrases":[],"wrongParaphrases":["personal opinions","strong feelings","general rules"],"misleadingDistractors":["absolute proof that cannot be questioned","a personal opinion based on feelings","a rule that must be followed"],"teacherNote":"Uncountable noun: facts, information or examples that support a conclusion, claim or judgement (some evidence, a piece of evidence; not “evidences”). It is not the same as proof, which means complete and final certainty."}]'::jsonb,'["evident","evidently"]'::jsonb,'["strong evidence","evidence to support","gather evidence"]'::jsonb,'live'),
('vocab_guidance','guidance','noun','help, advice or direction that helps someone to decide what to do','[{"senseId":"guidance_1","meaning":"help, advice or direction that helps someone to decide what to do","acceptedParaphrases":["helpful advice","support in making decisions"],"masteryContexts":[{"contextId":"u6_22_guidance_meaning","text":"The school offers career guidance to students who are not sure which subjects to study at university.","meaning":"advice that helps someone to decide","wrongMeanings":["orders that students must obey","rules about uniform and behaviour","results of an entrance test"]},{"contextId":"u6_22_guidance_paraphrase","text":"Without guidance from an experienced coach, young athletes can easily develop bad habits.","meaning":"help and direction from someone with experience","wrongMeanings":["punishment from a strict teacher","payment for a training course","praise for a good performance"]}],"situationDistractors":["The cleaner swept the corridor and locked the cupboard.","The concert began at seven, and the audience clapped loudly after every song.","Anna was told that she must hand in her phone before the test started.","The flight to Singapore was delayed because of thick fog over the airport.","Rosa polished her shoes and put on her best jacket.","The two teams shook hands before the match began."],"gapDistractors":[{"contextId":"u6_22_guidance_gap_1","answer":"guidance","wrong":["luggage","furniture","clothing"]},{"contextId":"u6_22_guidance_gap_2","answer":"guidance","wrong":["clothing","luggage","sunshine"]},{"contextId":"u6_22_guidance_gap_3","answer":"guidance","wrong":["posters","uniforms","textbooks"]}],"spellingErrors":["guidence","gidance","guidanse","guadance","guidanc","guiadance"],"masteryPassages":[{"passageId":"u6_22_guidance_passage_1","contextId":"u6_22_guidance_gap_1","text":"First-year students are often unsure which courses to choose. The university therefore provides ____ through a team of advisers, who explain the options but leave the final decision to each student.","answer":"guidance"},{"passageId":"u6_22_guidance_passage_2","contextId":"u6_22_guidance_gap_2","text":"Young athletes can develop poor habits if they train alone. With ____ from an experienced coach, they learn to improve safely and to understand why each exercise matters.","answer":"guidance"}],"contextDependentParaphrases":[],"wrongParaphrases":["strict orders","school rules","final decisions"],"misleadingDistractors":["an order that must be obeyed immediately","a set of rules for a school","a test that checks what you know"],"teacherNote":"Uncountable noun: help, advice or direction that helps someone to decide what to do (guidance from a teacher, career guidance). It is not an order or a rule: the person who receives guidance still makes the final decision. Not “a guidance” or “guidances”."}]'::jsonb,'[]'::jsonb,'["career guidance","guidance from a teacher","provide guidance"]'::jsonb,'live'),
('vocab_academic','academic','adjective','connected with education, studying or scholarly work','[{"senseId":"academic_1","meaning":"connected with education, studying or scholarly work","acceptedParaphrases":["study-related","related to higher education"],"masteryContexts":[{"contextId":"u6_23_academic_meaning","text":"Students who read widely often achieve better academic results than those who read only their textbooks.","meaning":"connected with studying and education","wrongMeanings":["connected with sport and exercise","connected with art and music","connected with money and trade"]},{"contextId":"u6_23_academic_paraphrase","text":"Mehmet moved abroad to continue his academic career as a researcher in a university laboratory.","meaning":"connected with scholarly work and study at a university","wrongMeanings":["connected with building and repair work","connected with farming and food","connected with travel and tourism"]}],"situationDistractors":["The football team trained twice a week and won the league for the first time.","A chef tasted the soup and added a little more salt.","The tourists took a boat across the lake and photographed the mountains.","The caretaker wiped his hands and closed the garage door for the night.","The tourists queued for an hour to buy tickets for the boat trip.","Little by little the snow melted, and the rivers began to rise."],"gapDistractors":[{"contextId":"u6_23_academic_gap_1","answer":"academic","wrong":["seasonal","tropical","metallic"]},{"contextId":"u6_23_academic_gap_2","answer":"academic","wrong":["tropical","frozen","seasonal"]},{"contextId":"u6_23_academic_gap_3","answer":"academic","wrong":["tropical","metallic","frozen"]}],"spellingErrors":["academmic","acadamic","academik","accademic","academc","acedemic"],"masteryPassages":[{"passageId":"u6_23_academic_passage_1","contextId":"u6_23_academic_gap_1","text":"Nadia was an excellent footballer, but her parents also wanted her to succeed in her ____ work. She therefore agreed to finish her homework before every training session.","answer":"academic"},{"passageId":"u6_23_academic_passage_2","contextId":"u6_23_academic_gap_2","text":"A university looks for more than exam grades. Applicants are asked to describe their ____ interests, such as the subjects they enjoy reading about in their own time.","answer":"academic"}],"contextDependentParaphrases":[],"wrongParaphrases":["sport-related","travel-related","health-related"],"misleadingDistractors":["connected with sport and physical exercise","too theoretical to be useful in real life","connected with the arts and entertainment"],"teacherNote":"Taught in its main sense: connected with education, studying or scholarly work (academic subjects, academic performance). The sense of “theoretical rather than practical” (an academic question) is not the focus here."}]'::jsonb,'[]'::jsonb,'["academic achievement","academic performance","academic subjects"]'::jsonb,'live'),
('vocab_concentration','concentration','noun','the ability to keep your full attention on one thing for a period of time','[{"senseId":"concentration_1","meaning":"the ability to keep your full attention on one thing for a period of time","acceptedParaphrases":["full attention","ability to give attention to one task"],"masteryContexts":[{"contextId":"u6_24_concentration_meaning","text":"A short walk in fresh air can improve your concentration when you have been studying for several hours.","meaning":"the ability to give full attention to one thing","wrongMeanings":["a strong wish to finish a task","the amount of a substance in water","a feeling of tiredness after exercise"]},{"contextId":"u6_24_concentration_paraphrase","text":"The surgeon needed complete concentration during the long operation, so nobody was allowed to speak to her.","meaning":"full attention on one task","wrongMeanings":["a fear of making a mistake","pride in a good result","a desire to be the best"]}],"situationDistractors":["The bakery opens at six and sells fresh bread to workers on their way to the factory.","Pablo saved enough money to buy a second-hand bicycle.","The old bridge was closed because of the flood.","Dad bought a newspaper and read it on the train to work.","The two sisters shared a taxi and arrived at the airport together.","The class painted pictures of their favourite animals and hung them on the wall."],"gapDistractors":[{"contextId":"u6_24_concentration_gap_1","answer":"concentration","wrong":["handwriting","appetite","height"]},{"contextId":"u6_24_concentration_gap_2","answer":"concentration","wrong":["popularity","permission","distance"]},{"contextId":"u6_24_concentration_gap_3","answer":"concentration","wrong":["hunger","eyesight","handwriting"]}],"spellingErrors":["concentraton","consentration","concentrasion","concentation","concentratoin","concentrashun"],"wordFamilyForms":[{"form":"concentration","partOfSpeech":"noun","example":"A quiet room helps students to keep their concentration during a long examination.","pedagogicallyUseful":true},{"form":"concentrate","partOfSpeech":"verb","example":"Many students find it easier to concentrate after a short walk.","pedagogicallyUseful":true,"altExample":"Please switch off your phones so that everyone can concentrate on the task."},{"form":"concentrated","partOfSpeech":"adjective","example":"Two hours of concentrated study are worth more than five hours of distracted work.","pedagogicallyUseful":true,"altExample":"After a concentrated session of revision, Leila felt ready for the test."}],"masteryPassages":[{"passageId":"u6_24_concentration_passage_1","contextId":"u6_24_concentration_gap_1","text":"After two hours of continuous reading, many students notice that their minds begin to wander. A short walk or a glass of water can restore their ____ so that they can continue working.","answer":"concentration"},{"passageId":"u6_24_concentration_passage_2","contextId":"u6_24_concentration_gap_2","text":"The surgeon asked everyone to leave the room during the delicate operation. Complete ____ was essential, because even a small mistake could harm the patient.","answer":"concentration"}],"contextDependentParaphrases":[],"wrongParaphrases":["strong feelings","quick decisions","good manners"],"misleadingDistractors":["the reason why someone wants to work","the amount of a substance in a liquid","a feeling of worry before an important test"],"teacherNote":"Uncountable in this sense: the ability to keep your full attention on one thing for a period of time (lose your concentration, concentration on a task). Boundary: focus (verb) is the act of directing attention; concentration is the ability to keep it there. It is not motivation, which is the reason you want to do something. The chemical sense (the concentration of salt in water) is not taught here."}]'::jsonb,'["concentrate","concentrated"]'::jsonb,'["lose concentration","concentration on a task","require concentration"]'::jsonb,'live'),
('vocab_complex','complex','adjective','made of many connected parts and difficult to understand or deal with','[{"senseId":"complex_1","meaning":"made of many connected parts and difficult to understand or deal with","acceptedParaphrases":["made up of many connected parts","hard to understand because of its many parts"],"masteryContexts":[{"contextId":"u6_25_complex_meaning","text":"The causes of climate change are complex, because natural cycles and human activity affect each other in many ways.","meaning":"made of many connected parts","wrongMeanings":["hard to do but simple in structure","new and not yet tested","old and no longer useful"]},{"contextId":"u6_25_complex_paraphrase","text":"The software looks simple, but its settings are complex, and beginners often spend hours learning how they affect one another.","meaning":"difficult to understand because of many connected parts","wrongMeanings":["simple to use after one lesson","too expensive for most people","hard to see because it is small"]}],"situationDistractors":["The farmer fed the chickens and collected the eggs before breakfast.","Nadia waved to her friends and ran across the playground.","The shop sold only fruit, vegetables and fresh bread.","A boy carried a bucket of water from the well to the garden.","Nina folded the towels and put them in the cupboard.","A visitor photographed the market stalls and bought a scarf."],"gapDistractors":[{"contextId":"u6_25_complex_gap_1","answer":"complex","wrong":["musical","coastal","seasonal"]},{"contextId":"u6_25_complex_gap_2","answer":"complex","wrong":["emotional","popular","tragic"]},{"contextId":"u6_25_complex_gap_3","answer":"complex","wrong":["local","tiny","seasonal"]}],"spellingErrors":["complx","complax","compleks","comlex","complexx","compelx"],"masteryPassages":[{"passageId":"u6_25_complex_passage_1","contextId":"u6_25_complex_gap_1","text":"A national economy cannot be explained by a single cause. Prices, jobs, trade and government decisions all affect one another, which makes the system far too ____ for a simple answer.","answer":"complex"},{"passageId":"u6_25_complex_passage_2","contextId":"u6_25_complex_gap_2","text":"At first the board game seemed easy. After a few rounds, however, the players realised that its rules were ____: each move changed the value of several other pieces.","answer":"complex"}],"contextDependentParaphrases":[],"wrongParaphrases":["made of one simple part","built a long time ago","used by very few people"],"misleadingDistractors":["hard to do, but simple to understand","new and not yet tested by anyone","easy to use after a little practice"],"teacherNote":"Taught as an adjective: made of many connected parts and difficult to understand or deal with (a complex system, a complex problem). It is not the same as difficult: a task can be difficult without having many connected parts."}]'::jsonb,'[]'::jsonb,'["a complex problem","a complex system","increasingly complex"]'::jsonb,'live'),
('vocab_motivation','motivation','noun','the reason or desire that makes someone want to do something','[{"senseId":"motivation_1","meaning":"the reason or desire that makes someone want to do something","acceptedParaphrases":["the desire to keep going","reason for wanting to succeed"],"masteryContexts":[{"contextId":"u6_26_motivation_meaning","text":"Setting small weekly targets can increase a student’s motivation to continue with a long course.","meaning":"the desire to keep going","wrongMeanings":["the ability to give full attention","the plan for reaching a goal","the feeling of pride in work"]},{"contextId":"u6_26_motivation_paraphrase","text":"The company found that employees worked harder when managers recognised their good work, which raised motivation across the whole team.","meaning":"the reason that makes people want to work","wrongMeanings":["the rule that people must follow at work","the time when people finish work","the money that people receive for work"]}],"situationDistractors":["The train to the coast leaves from platform four at half past nine.","The students wrote down the homework and packed their bags.","A neighbour borrowed a ladder and returned it the next day.","The painter mixed blue and yellow to make green.","A man hung his coat on the hook and sat down to eat.","The lesson ended at noon, and the pupils ran out to the playground."],"gapDistractors":[{"contextId":"u6_26_motivation_gap_1","answer":"motivation","wrong":["transport","pollution","luggage"]},{"contextId":"u6_26_motivation_gap_2","answer":"motivation","wrong":["patience","balance","passport"]},{"contextId":"u6_26_motivation_gap_3","answer":"motivation","wrong":["uniform","schedule","qualification"]}],"spellingErrors":["motivasion","motivaton","mottivation","motovation","motivatoin","motivashun"],"wordFamilyForms":[{"form":"motivation","partOfSpeech":"noun","example":"Setting clear goals can increase students’ motivation to keep learning.","pedagogicallyUseful":true},{"form":"motivate","partOfSpeech":"verb","example":"Good teachers know how to motivate their students.","pedagogicallyUseful":true,"altExample":"A clear reward system can motivate even the most reluctant learners."},{"form":"motivated","partOfSpeech":"adjective","example":"Highly motivated learners are more likely to finish the course.","pedagogicallyUseful":true,"altExample":"She stayed motivated throughout the course because she could see her progress."}],"masteryPassages":[{"passageId":"u6_26_motivation_passage_1","contextId":"u6_26_motivation_gap_1","text":"Rania started the course with great energy, but after a month of slow progress she began to skip lessons. Her teacher suggested small weekly goals, which gave her new ____ to continue.","answer":"motivation"},{"passageId":"u6_26_motivation_passage_2","contextId":"u6_26_motivation_gap_2","text":"Managers often assume that salary is the only reason people work hard. However, surveys show that recognition, interesting tasks and a sense of purpose provide strong ____ for many employees.","answer":"motivation"}],"contextDependentParaphrases":[],"wrongParaphrases":["the ability to stay calm","the wish to be alone","the need to rest"],"misleadingDistractors":["the ability to give full attention to one task","a plan for how to reach a goal","a feeling of pride after finishing a task"],"teacherNote":"Uncountable in this sense: the reason or desire that makes someone want to do something (lose motivation, motivation to learn). It is not concentration, which is the ability to give full attention to one thing."}]'::jsonb,'["motivate","motivated"]'::jsonb,'["lose motivation","motivation to learn","a source of motivation"]'::jsonb,'live'),
('vocab_curiosity','curiosity','noun','a strong desire to know, learn or understand something','[{"senseId":"curiosity_1","meaning":"a strong desire to know, learn or understand something","acceptedParaphrases":["strong wish to learn","eagerness to find things out"],"masteryContexts":[{"contextId":"u6_27_curiosity_meaning","text":"The teacher encouraged curiosity by asking students to write down questions about anything that surprised them.","meaning":"a strong desire to learn","wrongMeanings":["a fear of making mistakes","a wish to win a prize","a feeling of boredom"]},{"contextId":"u6_27_curiosity_paraphrase","text":"Her curiosity about how engines work led her to take apart an old motorbike.","meaning":"a strong wish to understand","wrongMeanings":["a worry about breaking something","a plan to earn some money","a habit of arriving late"]}],"situationDistractors":["The bus was full, so the passengers stood in the aisle.","Tom put the plates in the dishwasher and wiped the table.","The football match ended in a draw after a very quiet second half.","The rain stopped, and the children ran out to play in the puddles.","He parked the car, locked the doors and walked to the station.","The bakery sold out of bread before nine o’clock."],"gapDistractors":[{"contextId":"u6_27_curiosity_gap_1","answer":"curiosity","wrong":["politeness","tiredness","loneliness"]},{"contextId":"u6_27_curiosity_gap_2","answer":"curiosity","wrong":["complaint","insurance","journey"]},{"contextId":"u6_27_curiosity_gap_3","answer":"curiosity","wrong":["hunger","strength","temper"]}],"spellingErrors":["curiousity","curosity","curiosty","curiocity","cuirosity","curiossity"],"masteryPassages":[{"passageId":"u6_27_curiosity_passage_1","contextId":"u6_27_curiosity_gap_1","text":"The boy took apart a broken radio just to see how it worked. His ____ annoyed his father at first, but it eventually led him to a career in electronics.","answer":"curiosity"},{"passageId":"u6_27_curiosity_passage_2","contextId":"u6_27_curiosity_gap_2","text":"Good science teachers do not simply give answers. They encourage ____ by asking questions such as “Why do you think that happened?” and by welcoming unexpected ideas.","answer":"curiosity"}],"contextDependentParaphrases":[],"wrongParaphrases":["strong fear of failure","great pride in work","deep respect for rules"],"misleadingDistractors":["a wish to know about other people’s private lives","a feeling of fear about new experiences","a belief that you can do something well"],"teacherNote":"Uncountable in this sense: a strong desire to know, learn or understand something (curiosity about science, natural curiosity). It is positive here and is not the same as nosiness, which means wanting to know about other people’s private lives."}]'::jsonb,'[]'::jsonb,'["natural curiosity","curiosity about","satisfy your curiosity"]'::jsonb,'live'),
('vocab_technique','technique','noun','a particular skilled method of doing something','[{"senseId":"technique_1","meaning":"a particular skilled method of doing something","acceptedParaphrases":["skilled method","particular way of doing a task"],"masteryContexts":[{"contextId":"u6_28_technique_meaning","text":"Learning a simple breathing technique can help athletes to stay calm before an important race.","meaning":"a particular skilled method","wrongMeanings":["a general plan for a whole season","a rule that all athletes follow","a prize for the best athlete"]},{"contextId":"u6_28_technique_paraphrase","text":"The artist explained that her painting technique depends on thin layers of colour that dry quickly.","meaning":"a skilled way of doing something","wrongMeanings":["a long plan for selling paintings","a place where artists meet","a rule about painting in public"]}],"situationDistractors":["The waiter brought the menu and filled the glasses with water.","A cyclist stopped to fix a flat tyre by the side of the road.","The twins argued about whose turn it was to wash the dishes.","The pupils lined up quietly and waited for the headteacher.","A pigeon landed on the window sill and flew away again.","Jamal poured hot water into the cup and added a spoonful of sugar."],"gapDistractors":[{"contextId":"u6_28_technique_gap_1","answer":"technique","wrong":["subject","excuse","rumour"]},{"contextId":"u6_28_technique_gap_2","answer":"technique","wrong":["holiday","permission","budget"]},{"contextId":"u6_28_technique_gap_3","answer":"technique","wrong":["mistake","excuse","rumour"]}],"spellingErrors":["technic","techneque","tecnique","techniqe","techinique","tehnique"],"masteryPassages":[{"passageId":"u6_28_technique_passage_1","contextId":"u6_28_technique_gap_1","text":"The guitarist could already play every note of the song. He practised the same short piece for weeks, not to learn the notes, but to improve his ____ for changing chords quickly without any pause.","answer":"technique"},{"passageId":"u6_28_technique_passage_2","contextId":"u6_28_technique_gap_2","text":"Two runners had the same strength, yet one always finished ahead. The coach explained that her ____ was better: she landed lightly, kept her arms relaxed and wasted no energy.","answer":"technique"}],"contextDependentParaphrases":[],"wrongParaphrases":["general plan","useful tool","fixed rule"],"misleadingDistractors":["a general plan for achieving a long-term goal","a machine that is used in a laboratory","a rule that all players must follow"],"teacherNote":"Countable noun: a particular skilled method of doing something (a revision technique, a breathing technique). It is narrower than a strategy, which is a general plan for reaching a goal and may include several techniques."}]'::jsonb,'[]'::jsonb,'["a revision technique","learn a technique","breathing technique"]'::jsonb,'live'),
('vocab_effective','effective','adjective','successful in producing the result that was intended','[{"senseId":"effective_1","meaning":"successful in producing the result that was intended","acceptedParaphrases":["successful in getting good results","able to produce the intended result"],"masteryContexts":[{"contextId":"u6_29_effective_meaning","text":"Many doctors say that regular exercise is one of the most effective ways of reducing stress.","meaning":"successful in producing the intended result","wrongMeanings":["working quickly without wasting time","costing very little money","popular with a large number of people"]},{"contextId":"u6_29_effective_paraphrase","text":"The advertising campaign was not effective: sales did not rise, even though millions of people saw the posters.","meaning":"producing the intended result","wrongMeanings":["seen by a large number of people","paid for by a famous company","finished before the planned date"]}],"situationDistractors":["The pupils lined up quietly and followed the guide into the museum.","Sara packed a sandwich, an apple and a bottle of water for the journey.","The tennis match was stopped because the court was too wet to play on.","The plane landed safely, and the passengers collected their bags.","Mina wrote a short note and left it on the kitchen table.","The shop assistant gave the customer her change and a receipt."],"gapDistractors":[{"contextId":"u6_29_effective_gap_1","answer":"effective","wrong":["pleasant","traditional","familiar"]},{"contextId":"u6_29_effective_gap_2","answer":"effective","wrong":["resistant","allergic","popular"]},{"contextId":"u6_29_effective_gap_3","answer":"effective","wrong":["angry","anxious","unfriendly"]}],"spellingErrors":["effectve","efective","effektive","effecttive","effectiv","effectave"],"wordFamilyForms":[{"form":"effective","partOfSpeech":"adjective","example":"Short, regular sessions are an effective way to learn vocabulary.","pedagogicallyUseful":true},{"form":"effectively","partOfSpeech":"adverb","example":"Teachers who communicate effectively can explain difficult ideas in simple language.","pedagogicallyUseful":true},{"form":"effectiveness","partOfSpeech":"noun","example":"Researchers measured the effectiveness of the programme by comparing test scores.","pedagogicallyUseful":true},{"form":"ineffective","partOfSpeech":"adjective","example":"The warning signs were ineffective because nobody could read them from the road.","pedagogicallyUseful":true}],"masteryPassages":[{"passageId":"u6_29_effective_passage_1","contextId":"u6_29_effective_gap_1","text":"The school tried posters, assemblies and letters to reduce lateness, but nothing changed. When it introduced a short breakfast club, the number of late arrivals fell sharply, so the club proved to be far more ____.","answer":"effective"},{"passageId":"u6_29_effective_passage_2","contextId":"u6_29_effective_gap_2","text":"A good medicine must do more than exist; it must be ____ when patients use it. Doctors therefore compare patients who take the medicine with similar patients who do not.","answer":"effective"}],"contextDependentParaphrases":[],"wrongParaphrases":["quick to start work","cheap to produce","popular with many people"],"misleadingDistractors":["working quickly without wasting time","costing very little money to use","popular with a large number of people"],"teacherNote":"Taught as an adjective: successful in producing the intended result (an effective method). It is about whether something works, not how quickly or economically it works, which is efficient. The noun effect is a different word."}]'::jsonb,'["effectively","effectiveness","ineffective"]'::jsonb,'["an effective method","highly effective","an effective way of"]'::jsonb,'live'),
('vocab_inefficient','inefficient','adjective','not working or being organised in a way that uses time, effort or resources well','[{"senseId":"inefficient_1","meaning":"not working or being organised in a way that uses time, effort or resources well","acceptedParaphrases":["wasteful of time and effort","not using resources well"],"masteryContexts":[{"contextId":"u6_30_inefficient_meaning","text":"Walking to three different offices to collect one signature is an inefficient way of getting permission.","meaning":"wasting time and effort","wrongMeanings":["not producing the intended result","very expensive to repair","too difficult for most people"]},{"contextId":"u6_30_inefficient_paraphrase","text":"Old light bulbs are inefficient because most of the electricity they use is lost as heat instead of light.","meaning":"not using energy or resources well","wrongMeanings":["not safe for the people who use it","not popular with the shops that sell it","not available in very cold weather"]}],"situationDistractors":["The students filled in the form and handed it to the receptionist.","A tourist photographed the fountain and then bought an ice cream.","After the storm, the villagers repaired the roof and cleaned the street.","Heavy rain fell all afternoon, so the match was moved indoors.","The students sat in a circle and took turns to read aloud.","A waiter carried three plates of soup to the corner table."],"gapDistractors":[{"contextId":"u6_30_inefficient_gap_1","answer":"inefficient","wrong":["dishonest","generous","talkative"]},{"contextId":"u6_30_inefficient_gap_2","answer":"inefficient","wrong":["impolite","unsafe","unfair"]},{"contextId":"u6_30_inefficient_gap_3","answer":"inefficient","wrong":["illegal","unsafe","unlucky"]}],"spellingErrors":["inefficeint","inefficent","inneficient","ineficient","inefficiant","inefisient"],"wordFamilyForms":[{"form":"inefficient","partOfSpeech":"adjective","example":"Heating an empty building all night is inefficient and expensive.","pedagogicallyUseful":true},{"form":"inefficiency","partOfSpeech":"noun","example":"The report identified several causes of inefficiency in the hospital’s booking system.","pedagogicallyUseful":true},{"form":"inefficiently","partOfSpeech":"adverb","example":"Workers who use their time inefficiently often have to stay late.","pedagogicallyUseful":true},{"form":"efficient","partOfSpeech":"adjective","example":"The new machine is far more efficient than the old one, using half as much electricity.","pedagogicallyUseful":true}],"masteryPassages":[{"passageId":"u6_30_inefficient_passage_1","contextId":"u6_30_inefficient_gap_1","text":"In the old office, every form had to be signed by five different managers in five different buildings. The system was not impossible, but it was deeply ____, because it wasted days of staff time.","answer":"inefficient"},{"passageId":"u6_30_inefficient_passage_2","contextId":"u6_30_inefficient_gap_2","text":"Energy experts often give a simple example. A kettle that is filled to the top for a single cup is ____: most of the electricity heats water that nobody will use.","answer":"inefficient"}],"contextDependentParaphrases":[],"wrongParaphrases":["careless about safety","proud of past results","afraid of new ideas"],"misleadingDistractors":["not producing the intended result","very expensive to buy or repair","too complicated for most people to understand"],"teacherNote":"Taught as an adjective: not working or being organised in a way that uses time, effort or resources well (an inefficient system). It is not the same as ineffective, which means not producing the intended result: a method can work and still be inefficient."}]'::jsonb,'["inefficiency","inefficiently","efficient"]'::jsonb,'["an inefficient system","inefficient use of","highly inefficient"]'::jsonb,'live')
